import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"导读","description":"周易阐真 - 导读","frontmatter":{"title":"导读","description":"周易阐真 - 导读"},"headers":[],"relativePath":"zh/classics/chanzhen/001.md","filePath":"zh/classics/chanzhen/001.md"}'),s={name:"zh/classics/chanzhen/001.md"};function n(c,a,i,h,l,o){return t(),p("div",null,[...a[0]||(a[0]=[r('<h2 id="关于《易理阐真》-​" tabindex="-1">关于《易理阐真》 ​ <a class="header-anchor" href="#关于《易理阐真》-​" aria-label="Permalink to “关于《易理阐真》 ​”">​</a></h2><p>《易理阐真》是清代学者刘一明的作品，其道号为悟元子，是全真道龙门派第十一代宗师。这本书著于《三易注略》之后，共六卷，其中前四卷名为《周易阐真》，后两卷名为《孔易阐真》。卷首列有图说一卷，共四十余篇。书中前半部分主要推演河图洛书、先天后天之说，借易学来阐释丹家养生之术；后半部分则全系丹家之说。其注释宗旨与《三易注略》相同，以道家之言解易。《周易阐真》只释经文、卦爻辞，而不取十翼；《孔易阐真》则择释大象传及杂卦传，而不及一切经文。现存嘉庆二十四年（1819年）的重刊本。</p><p>刘一明在清乾隆年间修行于栖云山，深研易学兼通医术，认为易为“穷理尽性至命之学”，“丹道即易道，圣道即仙道”，其著作包括《周易阐真》、《义理阐微》、《指南针序》、《象言破疑》等。</p><h2 id="易理阐真-​" tabindex="-1">易理阐真 ​ <a class="header-anchor" href="#易理阐真-​" aria-label="Permalink to “易理阐真 ​”">​</a></h2><p>丹经之由，始于后汉魏伯阳真人。真人成道后，怜世之学人惑于旁门邪说，不知圣贤大道，每多空空一世，到老无成，遂准易道而作《参同契》，以明性命源流、阴阳真假、修持法则、功夫次序。托物取象，譬语多端，以性命、阴阳、刚柔谓之药物;以修持功夫次序谓之火候;以修持功夫不缺谓之煅炼;以勇猛精进谓之武火;以从容渐入谓之文火;以阴阳、刚柔、中正谓之结丹;以阴阳混成、刚柔悉化谓之丹熟;以无声无臭、神化不测谓之脱丹。其寓意亦如周易，拟诸其形容，象其物宜，始有金丹之名、丹法之说、修特性命之理。</p><p>《参同》一出，详明其备，大露天机矣。后之了道群真，皆祖《参同》譬象，各作丹经，发《参同》所末发，详而又详，明而又明，性命之理无余蕴矣。其如书愈多，而人愈感，后学之人不得真传，直以譬象为真实，或以坎离为心肾，或以震兑为肺肝，或以屯蒙为子午抽添，或以复姤为心肾气生，或以既济为心肾交合，甚至以阴阳为男女，以彼我为采战，以炼炼为炉火，以金丹为服食，以有为为搬运，以无为为空寂，皆认后天有形、有象之物，不知先天无形、无象之真，以一盲而引衆盲，埋没古人度世之婆心矣。</p><p>予自童子时，即知有此一大事因缘，留心参学，所遇缁黄，皆不出上行议论，彼时亦以为然，不敢非之，后遇龛谷老人，即分邪正，复遇仙留丈人，群疑尽失，始知丹道即易道，圣道即仙道。易非卜筮之书，乃穷理、尽性、至命之学也。</p><p>予不敢自私，爰于《三易注略》之后，体二师之旨，述伯阳之意，尽将丹法寓于周易图卦系辞之中，略譬象而就实义，去奥语而取常言，直指何者为药物，何者为火候，何者为进阳，何者为退阴，何者为下手，何者为止足，何者为煅炼，何者为温养，何者为结丹，何者为脱丹，何者为先天，何者为后天，何者为有为，何者为无为，何者为逆运，何者为顺行。其图像、卦象、爻象，细为分析，通部分作二股，一进阳，一运阴，承上起下，一气贯串，使学者易于阅看。</p><p>至于十翼，乃宣圣直言其理，学者自能推求，故余不及注，惟取大象传、杂卦传，略释数语，以备参考。其中重复语，亦如周易重复象，虽有重复语，并无重复意，书成之后，名曰《易理阐真》，乃阐其修持性命之真耳。</p><p>夫易，广矣，大矣。以言其远，则不御，以言其迩，则静而正;以言其天地之间，则备矣。所以，开物成务，通天下之志，定天下之业，断天下之疑，无所不包，无所不该，讵可就一事而论哉!然其归根处，总以穷理，尽性、至命为学。</p><p>阐真者，即阐其穷理之真，尽性之真、至命之真。先穷性命之理，后了性命之功，性命俱了，浑热天理，复见本来面目。在儒，则谓之明善复初;在道，则谓之还原返本。再加向上功夫，阴阳混化，无声无臭。在儒，则谓义精仁熟。至诚如神;在道，则为九还七返，形神俱妙。金丹之道尽，性命之功毕。</p><p>予之意如是，古来群真之意亦如是，即伯阳参同之意亦无不如是也。</p><p>时 大清嘉庆三年岁次戊午春王正月元宵节，素朴散人悟元子刘一明自序于自在窝中。</p><h2 id="杨芳灿序易理阐真-​" tabindex="-1">杨芳灿序易理阐真 ​ <a class="header-anchor" href="#杨芳灿序易理阐真-​" aria-label="Permalink to “杨芳灿序易理阐真 ​”">​</a></h2><p>自秦焚典策，惟《易》以卜筮之书，仅得不毁。汉除挟书之律，《易经》始置博士，而焦京田孟之属，大多以灼揲占验为能，遂使圣神授受三古奥奇，或与风角鸟情视为小说家言，而《易》流为卜筮之书。逮后伯阳魏氏，始合三《易》，作《参同契》一书，扶羲、农、姬、孔之义蕴，衍河、洛图象之精深，人勰以天察之道而愈明，物性其情，验之身而益著。然其称物罕譬，寄寓窅深，后贤不察。又或以私意相揣，遂致异说蜂起，争以黄白吐纳为事，而《易》又流为炼度之书。</p><p>悟元道人者，金城栖云山之肥遁士也。其生平著述《三易注略》若干卷，余既序而传之矣。兹复出其《周易阐真》一编，索余为识其著书之由。盖道人以蚤年始学隐迹黄冠，神解超超，道心夙契。后遇龛谷老人，弥分邪正之源。又值仙留丈，尽抉元真之秘，以为丹道即易道也，圣道即仙道也。</p><p>《易》非卜筮炼度之书，实皆穷理、尽性、至命之学也。于是述伯阳之遗义，参神圣之蕴奇，取其龙蛇铅汞之法，验以爻系图象之说，别其劣歧，归于宗主，其辞约、其义繁、其文浅、其指深，取类极迩，而见道甚远，其身心性命之功，殆不谬乎。吾儒之为之者，呜呼!若道人者，庶可与言易哉!</p><p>《易》曰：“成性存存，道义之门”。又曰：“一阴一阳之谓道。继之者善也，成之者性也。仁者见之谓之仁，智者见之谓之智，百姓日用而不知，故君子之道鲜矣。”</p><p>今以道人之书观之，元微杳邈，与道大适，不必标奇领异而已，得《易》之简能之妙。所谓苟非其人，道不虚行。彼执金堤水防之言，务熊经鸟伸之术，其于伯阳氏之书，犹未尝升其堂而哜其胔也，何足以尽《易》之蕴乎!</p><p>昔唐道士王远知，著有《易总》，忽一日，雷电晦冥，似有神物取去。今道人此书，当敬慎护持，勿尽泄造化之秘藏，致烦丁甲也。</p><p>嘉庆 庚申夏 梁溪杨芳灿序 易理阐真序</p>',21)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
